#!/usr/bin/env bash
# Writes frontend/config.js from Terraform outputs, uploads the SPA to S3 and
# invalidates the CloudFront cache. Run after `terraform apply`.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
out() { "$ROOT/scripts/tf-outputs.sh" "$@"; }

SITE_URL="$(out site_url)"
BUCKET="$(out frontend_bucket)"
DIST_ID="$(out cloudfront_distribution_id)"

cat > "$ROOT/frontend/config.js" <<EOF
// Generated by scripts/deploy-frontend.sh - do not edit by hand.
window.APP_CONFIG = {
  region: "$(out aws_region)",
  userPoolId: "$(out user_pool_id)",
  clientId: "$(out user_pool_client_id)",
  cognitoDomain: "$(out cognito_domain)",
  redirectUri: "${SITE_URL}/",
  maxUploadBytes: $(out max_upload_bytes)
};
EOF

aws s3 sync "$ROOT/frontend/" "s3://$BUCKET/" --delete \
  --cache-control "no-cache" --only-show-errors
aws cloudfront create-invalidation --distribution-id "$DIST_ID" --paths "/*" \
  --query 'Invalidation.Id' --output text >/dev/null

echo "Frontend deployed to $SITE_URL"
